# ============================================================ ARTÍCULO 1 — מה השמחה
BLOQUES.append({"t": "titulo",
  "he": "מָה הַשִּׂמְחָה?",
  "es": "¿Cuál es la alegría?"})

BLOQUES.append({"t": "par",
  "he": "בְּסִיּוּם חַג הַסּוּכּוֹת אֲנַחְנוּ מְסַיְּימִים אֶת הַתּוֹרָה. הַחֵל מִשְּׁלֹהִי זְמַן הַגְּאוֹנִים אֲנַחְנוּ חוֹגְגִים אֶת שְׁמִינִי עֲצֶרֶת כְּ\"שִׂמְחַת תּוֹרָה\". בְּנֵי אֶרֶץ יִשְׂרָאֵל לֹא יָכְלוּ לַחְגֹּג שִׂמְחַת תּוֹרָה, מִשּׁוּם שֶׁהָיוּ מְסַיְּימִים אֶת קְרִיאַת הַתּוֹרָה רַק פַּעַם בְּשָׁלוֹשׁ שָׁנִים. אֲבָל לְפִי מִנְהַג בָּבֶל, שֶׁהִתְקַבֵּל בְּהֶמְשֵׁךְ בְּכָל תְּפוּצוֹת יִשְׂרָאֵל, קוֹרְאִים בְּכָל שָׁבוּעַ פָּרָשָׁה וּמְסַיְּימִים אֶת הַתּוֹרָה בְּשִׂמְחַת תּוֹרָה.",
  "es": "Al terminar la fiesta de Sucot terminamos la Torá. Desde finales de la época de los Gueoním celebramos Shminí Atzéret como «Simjat Torá». Los habitantes de la Tierra de Israel no podían celebrar Simjat Torá, porque terminaban la lectura de la Torá solo una vez cada tres años. Pero según la costumbre de Babilonia, que se aceptó después en toda la diáspora de Israel, se lee cada semana una <i>parashá</i> y se termina la Torá en Simjat Torá."})

BLOQUES.append({"t": "par",
  "he": "שְׁמִינִי עֲצֶרֶת אֵינוֹ חֵלֶק מֵחַג הַסּוּכּוֹת. אֵין יוֹשְׁבִים בּוֹ בַּסוּכָּה, וְאֵין נוֹטְלִים אֶת אַרְבַּעַת הַמִּינִים. בְּחָג הַזֶּה אֲנַחְנוּ נֶעֱצָרִים לִפְנֵי ה' וּשְׂמֵחִים לְפָנָיו. הַקֶּשֶׁר לְסִיּוּם הַתּוֹרָה וְסִיּוּם סֵפֶר דְּבָרִים לֹא הִתְחִיל מִימֵי הַגְּאוֹנִים. הוּא מוֹפִיעַ כְּבָר בַּתּוֹרָה עַצְמָהּ: מִצְוַת הַקְהֵל, הַמִּצְווָה הַיְּחִידָה מִן הַתּוֹרָה הַמְּחַיֶּיבֶת \"קְרִיאַת הַתּוֹרָה\" צִבּוּרִית (קְרִיאַת הַתּוֹרָה לְאֹרֶךְ הַשָּׁנָה הִיא תַּקָּנַת מֹשֶׁה רַבֵּנוּ, וּבְהֶמְשֵׁךְ תַּקָּנַת עֶזְרָא), שֶׁבָּהּ קוֹרֵא הַמֶּלֶךְ אֶת סֵפֶר מִשְׁנֵה תוֹרָה בְּחַג הַסּוּכּוֹת.",
  "es": "Shminí Atzéret no es parte de la fiesta de Sucot. No se habita en ella en la <i>sucá</i>, ni se toman las cuatro especies. En esta fiesta nos «detenemos» ante el Eterno y nos alegramos ante Él. El vínculo con la conclusión de la Torá y la conclusión del libro de Devarim no empezó en los días de los Gueoním. Ya aparece en la Torá misma: la mitzvá de <i>Hakhel</i>, la única mitzvá de la Torá que ordena una «lectura de la Torá» pública (la lectura de la Torá a lo largo del año es institución de Moshé, nuestro maestro, y después institución de Ezrá), en la que el rey lee el libro de <i>Mishné Torá</i> [Devarim] en la fiesta de Sucot."})

BLOQUES.append({"t": "par",
  "he": "מַדּוּעַ בְּסוּכּוֹת? וּמַדּוּעַ סֵפֶר מִשְׁנֵה תוֹרָה? חַכְמֵי הַקַּבָּלָה הִגְדִּירוּ אֶת הַסוּכָּה כְּ\"צִלָּא דִּמְהֵימְנוּתָא\". אַךְ מַדּוּעַ הַסוּכָּה נֶחְשֶׁבֶת לְצֵל הָאֱמוּנָה? אוֹר הַמַּקִּיף שֶׁל הַשְּׁכִינָה?",
  "es": "¿Por qué en Sucot? ¿Y por qué el libro de <i>Mishné Torá</i>? Los sabios de la Kabalá definieron la <i>sucá</i> como «<i>tzilá dimeheimnutá</i>», «sombra de la fe». Pero ¿por qué se considera a la <i>sucá</i> sombra de la fe? ¿La luz que envuelve a la <i>Shejiná</i>?"})

BLOQUES.append({"t": "par",
  "he": "הַהֶסְבֵּר הוּא, שֶׁמִּצְוַת הַשִּׂמְחָה בֶּחָג הִיא \"לִשְׂמֹחַ לִפְנֵי ה' שִׁבְעַת יָמִים\", וּמִן הַצַּד הַשֵּׁנִי: \"בַּסוּכּוֹת תֵּשְׁבוּ שִׁבְעַת יָמִים\". וְכָאן מִתְעוֹרֶרֶת שְׁאֵלָה: אֵיךְ אֶפְשָׁר לְקַיֵּים אֶת שְׁתֵּי הַמִּצְווֹת הָאֵלּוּ יַחְדָּיו? הַשִּׂמְחָה לִפְנֵי ה' הִיא בַּמִּקְדָּשׁ, אֲבָל צְרִיכִים לָשֶׁבֶת בַּסוּכּוֹת שִׁבְעַת יָמִים?",
  "es": "La explicación es que la mitzvá de la alegría en la fiesta es «alegraros ante el Eterno siete días», y por otro lado: «en cabañas habitaréis siete días». Y aquí surge una pregunta: ¿cómo se pueden cumplir estas dos mitzvot juntas? La alegría ante el Eterno es en el Templo, pero hay que sentarse en las cabañas siete días."})

BLOQUES.append({"t": "par",
  "he": "הַתְּשׁוּבָה הִיא, שֶׁחֵלֶק מֵעִנְיַן מִצְוַת הַסוּכָּה הוּא שִׁחְזוּר שֶׁל דּוֹר הַמִּדְבָּר, \"כִּי בַסֻּכּוֹת הוֹשַׁבְתִּי אֶת בְּנֵי יִשְׂרָאֵל\", \"עוֹד אוֹשִׁיבְךָ בָאֹהָלִים כִּימֵי מוֹעֵד\". כַּאֲשֶׁר אָדָם רוֹאֶה בָּתִּים עַל גִּבְעָה, לְדֻגְמָא, הוּא מֵבִין שֶׁיֵּשׁ כָּאן כְּפָר, אֲנָשִׁים גָּרִים כָּאן. אֲבָל כַּאֲשֶׁר הוּא רוֹאֶה אֹהָלִים וְסוּכּוֹת פְּזוּרִים עַל פְּנֵי הַשָּׂדֶה, הוּא מֵבִין שֶׁיֵּשׁ כָּאן אֵיזוֹ שֶׁהִיא עֲבוֹדָה, שֶׁאַנְשֵׁי מָקוֹם מְסֻיָּם, אוֹ פּוֹעֲלִים שֶׁל אָדוֹן מְסֻיָּם, מִתְקַבְּצִים כָּאן לְשֵׁם מְלֶאכֶת הָאָסִיף, אוֹ לְשֵׁם אֵיזוֹ חֲגִיגָה.",
  "es": "La respuesta es que parte del sentido de la mitzvá de la <i>sucá</i> es una recreación de la generación del desierto: «pues en cabañas hice habitar a los hijos de Israel», «aún te haré habitar en tiendas como en los días de la fiesta». Cuando una persona ve casas sobre una colina, por ejemplo, entiende que hay allí una aldea, que vive gente allí. Pero cuando ve tiendas y cabañas dispersas por el campo, entiende que hay allí algún tipo de trabajo: que gente de cierto lugar, o trabajadores de cierto patrón, se reúnen allí para la labor de la cosecha, o para alguna celebración."})

BLOQUES.append({"t": "par",
  "he": "הַסוּכּוֹת הֵן דִּירוֹת עֲרַאי, שֶׁבְּהֶכְרֵחַ טְפֵלוֹת לְאֵיזֶשֶׁהוּ מָקוֹם קֶבַע. כַּאֲשֶׁר בְּנֵי יִשְׂרָאֵל עָלוּ לָרֶגֶל, הֵם כְּמוֹ צֹאן, כְּצֹאן יְרוּשָׁלַיִם בְּמוֹעֲדֶיהָ. אַף עַל פִּי שֶׁהֵם מִתְגּוֹרְרִים בְּסוּכּוֹת וּבְאֹהָלִים סְבִיב הָעִיר, כָּל הַסוּכּוֹת הָאֵלּוּ טְפֵלוֹת לַמִּקְדָּשׁ, שָׁם שׁוֹכֶנֶת הַשְּׁכִינָה. וְלָכֵן כְּשֶׁיּוֹצְאִים מֵהַבַּיִת לַסוּכָּה, נֶהְפָּכִים לְצֹאנוֹ שֶׁל ה'. הַסוּכָּה טְפֵלָה לִמְקוֹם הַמִּקְדָּשׁ, הִיא צִלָּא דִּמְהֵימְנוּתָא. הִיא מְקוֹם מְנוּחָתָם וַאֲכִילָתָם שֶׁל הַמִּתְקַבְּצִים מִכָּל הָאָרֶץ כְּדֵי לִשְׁכֹּן בַּמִּקְדָּשׁ וְלִרְאוֹת פְּנֵי שְׁכִינָה.",
  "es": "Las cabañas son viviendas provisionales, subordinadas por fuerza a algún lugar fijo. Cuando los hijos de Israel subían en peregrinación, eran como ovejas, como el rebaño de Jerusalén en sus fiestas. Aunque habitan en cabañas y tiendas alrededor de la ciudad, todas esas cabañas están subordinadas al Templo, donde reside la <i>Shejiná</i>. Por eso, cuando se sale de casa a la <i>sucá</i>, uno se convierte en parte del rebaño del Eterno. La <i>sucá</i> está subordinada al lugar del Templo: es la sombra de la fe. Es el lugar de descanso y comida de los que se reúnen de toda la tierra para morar en el Templo y ver el rostro de la <i>Shejiná</i>."})

BLOQUES.append({"t": "par",
  "he": "וְכָךְ מוֹצְאִים אָנוּ בְּעוֹלֵי בָּבֶל, שֶׁלֹּא יָדְעוּ שֶׁיּוֹשְׁבִים בְּסוּכּוֹת. הַסִּבָּה הִיא, מִשּׁוּם שֶׁהַמִּצְווָה נִתְפְּסָה אֵצֶל בְּנֵי יִשְׂרָאֵל רַק כְּטָפֵלוּת לַמִּקְדָּשׁ וְלַשִּׂמְחָה לִפְנֵי ה', וּכְשֶׁחָרַב הַבַּיִת, חָשְׁבוּ שֶׁאֵין טַעַם בַּסוּכָּה, כִּי אֵין לְמָה לְהִטַּפֵּל. זוֹ כַּמּוּבָן טָעוּת מִבְּחִינָה הִלְכָתִית, וְלָכֵן הַדְּגֵשׁ הוּא עַל \"מָצְאוּ כָתוּב\": בְּאוֹתוֹ דּוֹר הוּבַן שֶׁאֵין לְהִסְתַּמֵּךְ רַק עַל מַה שֶּׁרְגִילִים וּמְקֻבָּל, אֶלָּא שֶׁהַתּוֹרָה שֶׁבְּעַל פֶּה מִתְיַשֶּׁבֶת עִם הַתּוֹרָה שֶׁבִּכְתָב, וְכָל מַה שֶּׁכָּתוּב חַיָּיב לְהִתְקַיֵּים. מִתּוֹךְ הֲבָנָה זוֹ, מוּבָן הַקֶּשֶׁר לְסֵפֶר מִשְׁנֵה תוֹרָה. אִם בְּסוּכּוֹת בְּנֵי יִשְׂרָאֵל שָׁבִים וּמְשַׁחְזְרִים אֶת הֱיוֹתָם צֹאנוֹ שֶׁל ה' בַּמִּדְבָּר, שֶׁטְּפֵלִים לַמִּשְׁכָּן, וּכְאִילּוּ אֵין לָהֶם עַכְשָׁו לֹא שָׂדוֹת וְלֹא כְּרָמִים, לֹא בָּתִּים וְלֹא עָרִים, אֶלָּא הֵם יוֹשְׁבִים בְּאֹהָלִים וּבְדִירוֹת עֲרַאי סְבִיב הַמִּשְׁכָּן וּבְכָל מָקוֹם שֶׁהֵם, הִינָם שְׂמֵחִים לִפְנֵי ה' - הֲרֵי זֶה הַזְּמַן לְהַאֲזִין לִנְאוּמָיו שֶׁל הָרוֹעֶה הַגָּדוֹל, מֹשֶׁה בֶּן עַמְרָם. וְלָכֵן זֶה הַזְּמַן הַמַּתְאִים לְשִׂמְחַת תּוֹרָה שֶׁבִּכְתָב בִּכְלָל, שֶׁבְּסוּכּוֹת אָנוּ חוֹזְרִים לִהְיוֹת כְּמוֹ בְּנֵי יִשְׂרָאֵל דּוֹר מְקַבְּלֵי הַתּוֹרָה.",
  "es": "Y así encontramos en los que subieron de Babilonia, que no sabían que había que habitar en cabañas. La razón es que la mitzvá se entendía entre los hijos de Israel solo como subordinada al Templo y a la alegría ante el Eterno, y cuando fue destruido el Templo, pensaron que no había sentido en la <i>sucá</i>, porque no había a qué subordinarse. Esto es, por supuesto, un error desde el punto de vista halájico, y por eso el énfasis está en «encontraron escrito»: en aquella generación se entendió que no hay que apoyarse solo en lo habitual y aceptado, sino que la Torá oral se ajusta a la Torá escrita, y todo lo que está escrito debe cumplirse. A partir de este entendimiento se comprende el vínculo con el libro de <i>Mishné Torá</i>. Si en Sucot los hijos de Israel vuelven a recrear el haber sido el rebaño del Eterno en el desierto, subordinados al <i>Mishkán</i>, y como si ahora no tuvieran ni campos ni viñedos, ni casas ni ciudades, sino que habitan en tiendas y viviendas provisionales alrededor del <i>Mishkán</i> y en cualquier lugar que estén, se alegran ante el Eterno — este es el momento de escuchar los discursos del gran pastor, Moshé, hijo de Amrám. Y por eso este es el momento adecuado para la alegría de la Torá escrita en general, pues en Sucot volvemos a ser como los hijos de Israel de la generación que recibió la Torá."})

BLOQUES.append({"t": "par",
  "he": "וּבְכָל מָקוֹם שֶׁהֵם שְׂמֵחִים לִפְנֵי ה' - הָרֵי זֶה הַזְּמַן לְהַאֲזִין לִנְאוּמָיו שֶׁל הָרוֹעֶה הַגָּדוֹל, מֹשֶׁה בֶּן עַמְרָם. וְלָכֵן זֶה הַזְּמַן הַמַּתְאִים לְשִׂמְחַת תּוֹרָה שֶׁבִּכְתָב בִּכְלָל, שֶׁבְּסוּכּוֹת אָנוּ חוֹזְרִים לִהְיוֹת כְּמוֹ בְּנֵי יִשְׂרָאֵל דּוֹר מְקַבְּלֵי הַתּוֹרָה. שִׂמְחַת שְׁמִינִי עֲצֶרֶת הִיא שִׂמְחָה עַל הַשִּׂמְחָה, חָג עַל עֶצֶם זֶה שֶׁזָּכִינוּ עַכְשָׁו לַחְגֹּג שָׁבוּעַ יָמִים לִפְנֵי ה'. וַאֲנַחְנוּ מַמְשִׁיכִים לִקְרֹא בַּתּוֹרָה וְלִהְיוֹת אִתָּהּ כָּל הַשָּׁנָה, מַכְנִיסִים אוֹתָהּ אֵלֵינוּ הַבַּיְתָה.",
  "es": "Simjat Shminí Atzéret es alegría sobre la alegría, fiesta por el mero hecho de que ahora merecimos celebrar una semana entera ante el Eterno. Y seguimos leyendo la Torá y estando con ella todo el año, la llevamos con nosotros a casa."})

BLOQUES.append({"t": "par",
  "he": "סֵפֶר מִשְׁנֵה תוֹרָה, יֵשׁ בּוֹ בְּחִינַת \"כָּל הַתּוֹרָה\", כִּי הוּא הַשִּׂיא שֶׁל הֶסְבֵּר דֶּרֶךְ הַתּוֹרָה, מֹשֶׁה מְסַכֵּם לִבְנֵי יִשְׂרָאֵל אַחֲרֵי כָּל אַרְבָּעִים שְׁנוֹת לִמּוּד הַתּוֹרָה, מָה ה' אֱלֹהֶיךָ דּוֹרֵשׁ מֵעִמְּךָ, אַחֲרֵי שֶׁעָבְרוּ אֶת כָּל כּוּר הַבַּרְזֶל אַרְבָּעִים שָׁנָה, אֵלּוּ הַדְּבָרִים שֶׁהָיוּ צְרִיכִים לָקַחַת עִמָּם וּלְשַׁנֵּן בְּאָזְנֵיהֶם. וְדִבְרֵי מֹשֶׁה הָאַחֲרוֹנִים הֵם קְרִיאַת הַתּוֹרָה שֶׁאֲנַחְנוּ שׁוֹמְעִים שׁוּב וָשׁוּב בְּשִׂמְחַת תּוֹרָה.",
  "es": "El libro de <i>Mishné Torá</i> tiene en él el aspecto de «toda la Torá», porque es la culminación de la explicación del camino de la Torá: Moshé resume a los hijos de Israel, después de cuarenta años de estudio de la Torá, qué demanda de ti el Eterno, tu Dios, después de haber pasado por todo el horno de hierro durante cuarenta años; estas son las cosas que debían llevar consigo y repetir en sus oídos. Y las últimas palabras de Moshé son la lectura de la Torá que escuchamos una y otra vez en Simjat Torá."})
